import { useState, useEffect } from 'react';
import { useParams, useNavigate } from "react-router-dom";
import './editor.css';
import Editor from "@monaco-editor/react";
import Axios from 'axios';

function Editor1() {
  const { level } = useParams();
  const navigate = useNavigate();

  const [userCode, setUserCode] = useState("");
  const [fontSize, setFontSize] = useState(16);
  const [userLang, setUserLang] = useState("python");
  const [userOutput, setUserOutput] = useState("");
  const [expectedOutput, setExpectedOutput] = useState("");
  const [question, setQuestion] = useState("");
  const [loading, setLoading] = useState(false);

  // 🔹 Fetch question + expected output
  useEffect(() => {
    fetch(`http://localhost:5000/problem/${level}`)
      .then(res => res.json())
      .then(data => {
        setQuestion(data.description);
        setExpectedOutput(data.expected_output);
      });
  }, [level]);

  // 🔹 Normalize output (IMPORTANT)
  const normalize = (text) =>
    text
      .trim()
      .replace(/\r\n/g, "\n")
      .replace(/\s+/g, " ");

  // 🔹 Run & match code
  function compile() {
    setLoading(true);
    if (!userCode) return;

    Axios.post(`http://localhost:5000/run`, {
      code: userCode,
      language: userLang,
    })
      .then((res) => {
        const actual = normalize(res.data.stdout || "");
        const expected = normalize(expectedOutput || "");

        setUserOutput(actual);

        // ✅ MATCH CHECK
        if (actual === expected) {
          const completed =
            JSON.parse(localStorage.getItem("completedLevels")) || [];

          if (!completed.includes(Number(level))) {
            completed.push(Number(level));
            localStorage.setItem(
              "completedLevels",
              JSON.stringify(completed)
            );
          }

          alert(" Correct Output! Level Completed");
        } else {
          alert(" Output not matched");
        }
      })
      .catch(() => {
        setUserOutput("Error executing code");
      })
      .finally(() => {
        setLoading(false);
      });
  }

  return (
    <div className="container">
      <h2>Level {level}</h2>
      <p><b>Question:</b> {question}</p>

      <div className='headChoicePannel'>
        <div className='language'>
          <h2 id='headChoice'>Language</h2>
          <select
            className="selectLan"
            value={userLang}
            onChange={(e) => setUserLang(e.target.value)}
          >
            <option value="java">Java</option>
            <option value="python">Python</option>
            <option value="c">C</option>
            <option value="cpp">C++</option>
          </select>
        </div>

        <div style={{ marginTop: "10px" }}>
          <button onClick={() => setFontSize(fontSize + 2)}>➕</button>
          <button onClick={() => setFontSize(fontSize - 2)} disabled={fontSize <= 10}>➖</button>
        </div>
      </div>

      <button className="run-btn" onClick={compile}>
        Run Code
      </button>

      <Editor
        height="300px"
        theme="vs-dark"
        language={userLang}
        options={{
          fontSize: fontSize,
          minimap: { enabled: false },
        }}
        onChange={(value) => setUserCode(value)}
      />

      <h3>Output:</h3>
      <pre>{userOutput}</pre>

      <button onClick={() => navigate("/")}>
        Back to Levels
      </button>
    </div>
  );
}

export default Editor1;
